(()=>{
/* Prototipo de diseño aislado. Sin API, autenticación, reglas financieras ni escrituras externas.
   Importes y estados son escenarios fijos; no calcula cotizaciones ni confirma pagos. */
const q=new URLSearchParams(location.search),direction=q.get('direction')==='B'?'B':'A';
let screen=q.get('screen')||'cart',scenario=q.get('state')||'normal',method=q.get('method')||'pago_movil';
let selectedAddress='Casa',selectedShipping=['home','home'],created=false,reported=false,operationStatus='confirmed',editorTab='contenido',editingNew=false,dirty=false;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${(ICONS[n]||ICONS.tag).map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')}></${tag}>`).join('')}</svg>`;
const btn=(label,action,cls='primary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,action)=>btn(label,action,'link');
const heading=(eyebrow,title,sub='')=>`<div class="intro"><div class="eyebrow">${eyebrow}</div><h1 style="margin-top:6px">${title}</h1>${sub?`<p class="muted small">${sub}</p>`:''}</div>`;
const pill=(label,tone='')=>`<span class="pill ${tone}">${label}</span>`;
const notice=(title,body,tone='')=>`<div class="notice ${tone}">${title?`<strong>${title}</strong>`:''}${body}</div>`;
const total=(label='Total del pedido')=>`<div class="totals"><span>Productos · 2 unidades</span><b>$51,00</b><span>Envío · 2 entregas</span><b>$8,00</b><span class="grand">${label}</span><b class="grand">$59,00</b></div>`;
const photoCredit=()=>`<div class="credit">Fotografías reales autorizadas: Samsung, <a href="https://commons.wikimedia.org/wiki/File:SAMSUNG_EP-T4510_45W_POWER_ADAPER_BLACK_%26_USB_C_TO_C_CABLE.jpg" target="_blank" rel="noopener">Dinkun Chen · CC BY-SA 4.0</a>; lector UGREEN, <a href="https://commons.wikimedia.org/wiki/File:UGREEN_SD_Card_Reader.jpg" target="_blank" rel="noopener">Bejnamin · CC0</a>. Tamaño adaptado. Importes y tiendas de ejemplo.</div>`;
const P=[{title:'Samsung USB-C 45 W',subtitle:'EP-T4510 · Negro · Con cable',price:'$42,00',photo:'samsung',store:'HAYAZGO',delivery:'16–19 oct.',variant:'Negro · Con cable'},{title:'UGREEN lector SD',subtitle:'USB-A y USB-C · Gris y negro',price:'$9,00',photo:'lector',store:'Voltio',delivery:'16–19 oct.',variant:'Conexión USB-A'}];
function product(p,i,qty=false){return `<div class="productrow"><img class="thumb" src="assets/${p.photo}.webp" alt="${p.title}"><div class="grow"><strong>${p.title}</strong><div class="small muted" style="margin-top:3px">${p.variant}</div>${qty?`<div class="stepper"><button data-action="remove-${i}" aria-label="Quitar ${p.title}">${icon('minus')}</button><span aria-label="Cantidad">1</span><button data-action="quantity-${i}" aria-label="Aumentar cantidad de ${p.title}">${icon('plus')}</button></div>`:`<div class="small muted" style="margin-top:6px">1 unidad</div>`}</div><div class="price">${p.price}</div></div>`}
function deliveryLabel(i){return selectedShipping[i]==='home'?'A domicilio · $4,00':'Retiro · escenario sin confirmar';}
function addressRow(){return `<div class="fieldline">${icon('map-pin')}<div class="grow"><h3>${selectedAddress} · Ana Ejemplo</h3><p class="small muted">Av. Ejemplo, Chacao · Caracas</p><p class="small muted">Una dirección para las dos entregas.</p></div>${link('Cambiar','address')}</div>`;}
const sellerScreens=new Set(['store','products','editor','orders','operation','settings']);
const labels={cart:'Carrito',delivery:'Entrega',review:'Revisar y crear',method:'Pagar el pedido',payment:'Reportar pago',result:'Estado del pago',order:'Tu pedido',account:'Cuenta',store:'Mi tienda',products:'Productos',editor:'Producto',orders:'Pedidos',operation:'Detalle de entrega',settings:'Tu tienda',plan:'Plan de pago'};
const backMap={cart:'account',delivery:direction==='A'?'review':'cart',review:direction==='A'?'cart':'delivery',method:'order',payment:'method',result:'order',order:'account',account:'cart',store:'account',products:'store',editor:'products',orders:'store',operation:'orders',settings:'store',plan:'review'};
function progress(){if(['account',...sellerScreens].includes(screen))return '';let steps=direction==='A'?['Revisión','Pago']:['Entrega','Revisión','Pago'];let current=['method','payment','result','order'].includes(screen)?steps.length-1:screen==='delivery'?0:direction==='A'?0:1;if(screen==='cart')return '';return `<div class="progress" aria-label="Progreso de compra">${steps.map((s,i)=>`<span class="${i===current?'active':''}" ${i===current?'aria-current="step"':''}><b>${i<current?'✓':String(i+1).padStart(2,'0')}</b>${s}</span>`).join('')}</div>`;}
function top(){const seller=sellerScreens.has(screen);return `<div class="nav">${btn(icon('chevron-left'),'back','iconbtn','aria-label="Volver"')}<div class="navtitle">${labels[screen]||'HAYAZGO'}${seller?'<small>Voltio · tienda de ejemplo</small>':['method','payment','result','order'].includes(screen)?'<small>Pedido de ejemplo EJ-1042</small>':''}</div>${seller?btn(icon('settings'),'settings','iconbtn','aria-label="Configuración de tienda"'):screen==='cart'?btn(icon('user'),'account','iconbtn','aria-label="Ir a Cuenta"'):link('Ver pedido','order').replace('class="link"','class="link '+(['method','payment','result'].includes(screen)?'':'hidden')+'"')}</div>${progress()}`;}
function footer(label,value,cta,action,caption=''){return `<div class="fixed">${label?`<div class="row between"><span class="small muted">${label}</span><strong class="money sm code">${value}</strong></div>`:''}${btn(cta,action)}${caption?`<p class="caption">${caption}</p>`:''}</div>`;}
function sellerbar(active){const items=direction==='A'?[['store','receipt','Atención'],['products','package','Productos'],['settings','store','Tienda']]:[['store','layout-grid','Resumen'],['orders','receipt','Pedidos'],['products','package','Catálogo'],['settings','store','Tienda']];return `<nav class="sellerbar" aria-label="Navegación de Mi tienda">${items.map(([s,ic,l])=>btn(icon(ic)+l,s,active===s?'active':'',active===s?'aria-current="page"':'')).join('')}</nav>`;}
function cart(){let content=heading('Tu compra','Lo que elegiste.','2 productos · 2 tiendas · 2 entregas independientes');if(scenario==='stock')content+=`<section>${notice('Cambió la disponibilidad','Solo queda 1 lector SD. Conservamos la cantidad válida; revisa antes de continuar.','warn')}${link('Conservar 1 y revisar','reset')}</section>`;content+=direction==='A'?`<div class="ribbon">${icon('package')} Se envían por separado; pagas un solo pedido.</div>`:'';content+=P.map((p,i)=>`<div class="group"><div class="grouphead"><div class="row"><span class="number">${i+1}</span><span class="grouplabel">${p.store}</span></div><span class="small muted">Entrega ${i+1} de 2</span></div>${product(p,i,true)}<div class="subline">${icon('circle-check')} Disponible${direction==='B'?'<span>· Envío se define al continuar</span>':''}</div></div>`).join('');content+=`<section><p class="small muted">El envío y el total se confirman con tu dirección. Los precios se revalidan al continuar.</p></section>${photoCredit()}`;return [content,footer('Productos · envío por definir','$51,00',direction==='A'?'Revisar compra':'Elegir entrega',direction==='A'?'review':'delivery','Necesitas una sesión para crear el pedido.')];}
function delivery(){return [heading(direction==='A'?'Editar desde la revisión':'01 / Organiza tu compra',direction==='A'?'Entrega y dirección':'Cada entrega,<br>en su lugar.','Una dirección para todo el pedido.')+`<section class="stack gap24">${addressRow()}${P.map((p,i)=>`<div class="${direction==='B'?'railgroup':''}">${direction==='B'?`<span class="number">0${i+1}</span>`:''}<div class="grouphead"><h2>${p.store}</h2><span class="small muted">Entrega ${i+1} de 2</span></div><p class="small muted">${p.title} · 1 unidad</p><button class="choice selected" data-action="shipping-${i}"><span class="radio"></span><span class="grow"><span class="title">A domicilio</span><small class="muted" style="display:block">Estimado 16–19 oct. · ejemplo</small></span><span class="right">$4,00</span></button>${link('Ver modalidades de esta entrega','shipping-'+i)}</div>`).join('')}${notice('Cuando cambias la dirección','Se vuelven a consultar modalidades, plazos y costos de ambas entregas. Revisas el total antes de crear el pedido.')}</section>`,footer('Total de ejemplo','$59,00',direction==='A'?'Volver a la revisión':'Revisar pedido','review','Todavía no se crea el pedido.')];}
function review(){const content=heading(direction==='A'?'01 / Revisión de compra':'02 / Revisa antes de crear',direction==='A'?'Una última revisión.':'Tu compra,<br>bien resuelta.','Confirma destino, entregas e importe antes de crear el pedido.')+`<section class="stack gap16">${addressRow()}<div><div class="sectiontitle"><h2>Dos entregas</h2>${link('Editar','delivery')}</div>${P.map((p,i)=>`<div class="compactrow row"><span class="number">${i+1}</span><div class="grow"><h3>${p.store} · ${p.title}</h3><p class="small muted">1 unidad · ${deliveryLabel(i)} · 16–19 oct.</p></div><strong class="small">${p.price}</strong></div>`).join('')}</div><div class="fieldline">${icon('wallet')}<div class="grow"><h3>Pago completo</h3><p class="small muted">Este pedido incluye envío de vendedor. No admite anticipos o cuotas.</p></div>${link('Ver','plan')}</div><div class="${direction==='B'?'receipt':''}">${total()}</div>${notice('Al confirmar creas el pedido','Se aparta inventario y se vacía el carrito. Después eliges el método y recibes una cotización exacta. Aún no has pagado.')}</section>`;return [content,footer('Total del pedido','$59,00','Confirmar pedido','create','Crear el pedido no confirma ningún pago.')];}
function methods(){let content=heading('Pedido EJ-1042 · Creado','Ahora elige cómo pagar.','Pago completo · $59,00 USD de saldo. Todavía no hay un pago confirmado.');content+=`<section class="stack gap16">${notice('Pedido creado; pago pendiente','Si sales, puedes retomarlo desde Cuenta → Mis pedidos. Su vigencia la indica el pedido.')}<div><div class="eyebrow">En bolívares</div>${methodRow('pago_movil','Pago Móvil','Referencia obligatoria · comprobante opcional','smartphone')}${methodRow('transferencia_ves','Transferencia bancaria','Referencia y comprobante obligatorios','landmark')}</div><div><div class="eyebrow">En dólares</div>${methodRow('efectivo_usd','Efectivo en punto de retiro','Monto exacto · reporte sin comprobante obligatorio','banknote')}${methodRow('zelle','Zelle','Transferencia manual · cotización propia','wallet')}</div>${link('USDT (TRC-20) y condiciones','other-methods')}<p class="small muted">El importe exacto y cualquier comisión aparecen al solicitar la cotización. No se muestran proveedores inactivos.</p></section>`;return [content,footer('Saldo del pedido en USD','$59,00','Obtener monto exacto','quote','Cada método obtiene su propia cotización.')];}
function methodRow(code,title,sub,ic){return `<button class="choice ${method===code?'selected':''}" data-action="method-${code}" aria-pressed="${method===code}"><span class="radio"></span><span class="methodicon">${icon(ic)}</span><span class="grow"><span class="title">${title}</span><small class="muted" style="display:block">${sub}</small></span></button>`;}
function payment(){const cash=method==='efectivo_usd',other=['zelle','usdt_trc20'].includes(method),transfer=method==='transferencia_ves';const title=cash?'Efectivo en punto de retiro':transfer?'Transferencia bancaria':other?(method==='zelle'?'Zelle':'USDT · TRC-20'):'Pago Móvil';const expired=scenario==='expired';let content=`<div class="barhint">Cotización de ejemplo · escenario fijo del 14 oct. · no utilizable para pagar</div><div class="quote"><div class="row between"><h2>${title}</h2>${pill(expired?'Vencida':'Vence 18:30',expired?'danger':'warn')}</div><p class="label" style="margin-top:12px">${cash?'Importe de ejemplo en USD':other?'Importe exacto':'Importe de ejemplo en VES'}</p><div class="money code">${cash?'$59,00':other?'Pendiente de cotizar':'Bs 51.796,10'}</div><div class="small muted">Base $59,00 · comisión de ejemplo $0,00</div>${!cash&&!other?`<p class="small" style="margin-top:10px">877,90 Bs/USD · referencia histórica 14 oct.<br>BCV por respaldo DolarAPI${link('Detalle','rate')}</p>`:''}</div>`;
if(other){content+=`<section class="stack gap16">${notice('El monto lo fija el servidor','Este método usa su propia base de precio y conversión. La maqueta no inventa un importe ni copia el de Pago Móvil.')}<p class="small muted">${method==='zelle'?'Referencia y comprobante obligatorios.':'Hash de transacción de 64 caracteres; comprobante opcional. Red TRC-20.'}</p>${btn('Volver a los métodos','method','secondary')}${btn('Ver ejemplo completo en USD','cash','secondary')}</section>`;return [content,''];}
if(expired){content+=`<section class="stack gap16">${notice('Esta cotización venció','No pagues ni reportes con estos datos. Solicita una nueva y comprueba el monto y su vigencia.','error')}${btn('Actualizar cotización de ejemplo','renew')}${link('Ver pedido sin pagar','order')}</section>`;return [content,''];}
content+=`<section class="stack gap16">${cash?notice('Pago presencial de ejemplo','Coordina el punto autorizado en las instrucciones del pedido. No envíes dinero a datos de esta maqueta.'):`<div><div class="sectiontitle"><h2>Datos para pagar</h2>${link('Cambiar método','method')}</div><dl class="recipient"><dt>Banco</dt><dd>Banco de ejemplo (no operativo)</dd><dt>Titular</dt><dd>HAYAZGO · datos ficticios</dd><dt>${transfer?'Cuenta':'Teléfono'}</dt><dd><span class="copyline">${transfer?'0000 0000 00 0000000000':'0000 000 0000'}${btn(icon('copy'),'copy','',`aria-label="Copiar dato ficticio"`)}</span></dd><dt>Documento</dt><dd>J-00000000-0 · ficticio</dd></dl></div>`}<div><h2>${cash?'Registrar entrega de efectivo':'Después de transferir'}</h2><label class="field">Referencia ${cash?'(opcional)':'bancaria'}<input name="reference" autocomplete="off" placeholder="${cash?'Puedes dejarla vacía':'Escribe la referencia'}" ${cash?'':'required'}><span class="hint">${cash?'La plataforma debe verificar la recepción.':'No compartas claves ni códigos de acceso.'}</span></label><div class="field"><span>Comprobante (${transfer?'obligatorio':'opcional'})</span>${btn(icon('upload')+' '+(window.proofAttached?'Archivo de ejemplo adjunto':'Adjuntar comprobante de ejemplo'),'proof','secondary')}</div><div id="payment-validation" class="errortext" role="alert"></div></div>${notice('Se envía para verificar','Reportar el pago no lo marca como confirmado. Durante la verificación no se abre otro intento.')}</section>`;return [content,footer('',null,'Enviar para verificar','report','Simulación visual; no se envían pagos ni archivos.')];}
function result(){const confirmed=scenario==='confirmed',rejected=scenario==='rejected';return [`<div class="result"><div class="successmark">${icon(confirmed?'circle-check':rejected?'circle-alert':'hourglass')}</div><div class="eyebrow">Pago · ${confirmed?'Confirmado':rejected?'Rechazado':'En verificación'}</div><h1 style="margin-top:8px">${confirmed?'Pago confirmado.':rejected?'Este reporte necesita atención.':'Reporte recibido.<br>Ahora lo verificamos.'}</h1><p class="muted">${confirmed?'Estado posterior representado: la plataforma confirmó el pago. La interfaz no lo confirma por sí sola.':rejected?'Ejemplo de motivo: no pudimos relacionar la referencia con el monto. Revisa el motivo del pedido y la deuda real.':'Tu pedido sigue pendiente de confirmación del pago. No necesitas enviarlo otra vez.'}</p><div class="line row between"><span class="muted small">Pedido de ejemplo</span><strong>EJ-1042</strong></div><div class="line row between"><span class="muted small">Reporte de ejemplo</span><strong>${method==='efectivo_usd'?'$59,00':'Bs 51.796,10'}</strong></div><div class="timeline"><div class="event"><strong>Pedido creado</strong><p>Inventario apartado · pago pendiente</p></div><div class="event ${!confirmed&&!rejected?'active':''}"><strong>Reporte enviado</strong><p>La plataforma revisa la recepción</p></div><div class="event ${confirmed||rejected?'active':''}"><strong>${confirmed?'Pago confirmado':rejected?'Reporte rechazado':'Confirmación pendiente'}</strong><p>${confirmed?'La entrega puede avanzar según sus reglas':rejected?'Deuda pendiente de ejemplo: $59,00':'El seguimiento se actualiza al resolverse'}</p></div></div>${rejected?notice('Solo si el servidor permite reintentar','Primero recupera la deuda y el intento actual. Una respuesta perdida nunca justifica un pago duplicado.','warn'):''}</div>`,footer('',null,rejected?'Revisar pago pendiente':'Ver mi pedido',rejected?'retry-payment':'order',confirmed?'Estado ilustrativo, no confirmación operativa.':'Tu reporte se conserva en el pedido.')];}
function order(){const pending=reported||scenario==='pending',confirmed=scenario==='confirmed';return [heading('EJ-1042 · Pedido de ejemplo',pending?'Tu pago se está verificando.':confirmed?'Tu compra avanza.':'Tu pedido está creado.',pending?'No se ofrece un nuevo pago mientras se resuelve el reporte.':'Retoma el siguiente paso desde aquí.')+`<section class="stack gap24">${notice(pending?'Próxima acción: esperar verificación':confirmed?'Próxima acción: seguir entregas':'Próxima acción: completar el pago',pending?'Si necesitas ayuda, abre el detalle del reporte o contacta soporte.':confirmed?'Cada entrega mantiene su propio avance.':'Solicita una cotización vigente. No reutilices un monto anterior.',pending?'warn':'')}<div class="totals"><span>Total</span><b>$59,00</b><span>Pagado y confirmado</span><b>${confirmed?'$59,00':'$0,00'}</b><span>Saldo en USD</span><b>${confirmed?'$0,00':'$59,00'}</b></div><div><h2>Entregas por separado</h2>${P.map((p,i)=>`<div class="line"><div class="row between"><h3>${i+1} · ${p.store}</h3>${pill(confirmed?'Preparación pendiente':'Espera de pago',confirmed?'':'warn')}</div><p class="small muted" style="margin-top:6px">${p.title} · A domicilio</p></div>`).join('')}</div>${link('Calendario y movimientos','order-history')}${link('Ayuda con este pedido','support')}${!confirmed&&!pending?link('Condiciones para cancelar','cancel-order'):''}</section>`,footer('',null,pending?'Ver reporte en revisión':confirmed?'Ver seguimiento':'Continuar con el pago',pending?'result':confirmed?'tracking':'method',pending?'La plataforma confirma la recepción del dinero.':'Vigencia y acciones según el estado del pedido.')];}
function account(){return [`<div class="accountidentity"><div class="eyebrow">Tu espacio</div><h1 style="margin-top:6px">Hola, Ana.</h1><p class="small muted" style="margin-top:6px">ana@example.com · cuenta representativa</p></div><section><div class="eyebrow">Tus compras</div>${actionRow('receipt','Mis pedidos','Retoma el pago y sigue tus entregas','order')}${actionRow('heart','Favoritos','Productos guardados','favorites')}${actionRow('map-pin','Direcciones','Casa · Caracas','address')}<div class="divider"></div><div class="eyebrow">Tu negocio</div>${actionRow('store','Mi tienda','Voltio · atender pedidos y catálogo','store')}<p class="footnote">Este acceso solo aparece para integrantes autorizados de una tienda.</p><div class="divider"></div>${actionRow('settings','Preferencias y ayuda','Tu cuenta mantiene su contexto de comprador','preferences')}</section>`,buyerbar('account')];}
function actionRow(ic,title,sub,action){return `<button class="actionrow" data-action="${action}">${icon(ic)}<span class="grow"><strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</span>${icon('chevron-right')}</button>`;}
function buyerbar(active){return `<nav class="sellerbar" aria-label="Navegación de comprador">${[['cart','house','Inicio'],['cart','search','Buscar'],['cart','shopping-bag','Carrito'],['account','user','Cuenta']].map(([s,ic,l])=>btn(icon(ic)+l,s,l.toLowerCase()===active?'active':'')).join('')}</nav>`;}
function task(number,status,title,sub,action='operation',tone=''){return `<button class="task" data-action="${action}"><div class="row between"><strong>${number}</strong>${pill(status,tone)}</div><p class="small muted">${title}</p><div class="foot"><span>${sub}</span><span class="chevron">${icon('chevron-right')}</span></div></button>`;}
function store(){const content=`<div class="sellerintro"><div class="row between"><div class="row"><div class="lettermark">V</div><div><div class="eyebrow">${direction==='A'?'Mi tienda · atención':'Centro de negocio'}</div><h1>${direction==='A'?'Vamos a resolver.':'Voltio, en marcha.'}</h1></div></div>${btn(icon('chevron-down'),'stores','iconbtn','aria-label="Cambiar tienda autorizada"')}</div>${direction==='B'?'<p class="small muted" style="margin-top:12px">Miércoles, 14 de octubre · actividad de ejemplo</p>':''}</div>${direction==='B'?`<div class="stats"><div><strong>2</strong><small>Por preparar</small></div><div><strong>3</strong><small>En camino</small></div><div><strong>13</strong><small>Productos</small></div></div>`:''}<section class="stack gap16"><div class="sectiontitle"><h2>${direction==='A'?'Requieren atención':'01 · Atención'}</h2>${link('Ver pedidos','orders')}</div><div class="${direction==='B'?'taskblock':''}">${task('EJ-1041 · Entrega 1','Pago confirmado','1 × UGREEN lector SD · USB-A','Lista para preparar','operation','good')}${task('EJ-1038 · Entrega 1','Pago confirmado','2 × Lectores SD · USB-A','En preparación · falta despachar','dispatch','good')}</div>${notice('EJ-1042 · espera de pago','No preparar todavía. La plataforma confirma los pagos; la tienda actualiza sus entregas.','warn')}<div><div class="eyebrow">${direction==='B'?'02 · Catálogo':'Tu catálogo'}</div>${actionRow('package','13 productos · 1 en revisión','Abrir catálogo y editar existencias','products')}${btn(icon('plus')+' Crear producto','new-product','secondary')}</div>${direction==='B'?`<div><div class="eyebrow">03 · Tienda</div>${actionRow('store','Perfil y políticas','Información del negocio','settings')}</div>`:''}</section>`,bottom=sellerbar('store');return [content,bottom];}
function products(){const rows=[{...P[1],price:'$9,00',status:'Publicado',stock:'25 unidades',tone:'good'},{...P[0],price:'$42,00',status:'Publicado',stock:'6 unidades',tone:'good'},{title:'Nueva ficha de accesorio',subtitle:'Producto de ejemplo',price:'$18,00',photo:'lector',status:'En revisión',stock:'Aún no visible para comprar',tone:'warn'}];return [heading('Catálogo de Voltio',direction==='A'?'Productos al día.':'Tu catálogo,<br>en orden.','Existencias y publicación son estados distintos.')+`<section style="padding-block:10px"><div class="searchfield">${icon('search')}<input id="product-search" aria-label="Buscar en los productos cargados" placeholder="Buscar en esta lista"></div></section><div class="filtertags" aria-label="Filtrar productos cargados">${['Todos','Publicados','En revisión'].map((v,i)=>btn(v,'productfilter-'+i,i?'':'active',`aria-pressed="${!i}"`)).join('')}</div><section id="product-rows" style="padding-top:0">${rows.map((p,i)=>`<div class="row-edit" data-product="${i}" data-title="${p.title.toLowerCase()}"><img class="thumb" src="assets/${p.photo}.webp" alt="${p.title}"><div class="grow"><h3>${p.title}</h3><div class="row between" style="margin-top:7px"><strong>${p.price}</strong>${pill(p.status,p.tone)}</div><p class="small muted" style="margin-top:6px">${p.stock}</p><div class="editaction">${i<2?btn('Existencias','inventory',''):''}${btn('Editar','editor','')}</div></div></div>`).join('')}<p class="footnote">Filtrado de esta página de ejemplo. Una búsqueda en todo el catálogo requeriría un contrato adicional.</p></section>${photoCredit()}`,`<div class="fixed">${btn(icon('plus')+' Crear producto','new-product')}</div>${sellerbar('products')}`];}
function editor(){const tab=editorTab,content=heading(editingNew?'Nueva ficha · creación':'Edición · UGREEN lector SD',editingNew?'Una ficha clara.':'El producto, por partes.','Un solo guardado. Publicación sujeta a la revisión correspondiente.');const summary=`<div class="editorinfo row between"><div><strong>${editingNew?'Nueva ficha':'UGREEN lector SD'}</strong><p class="small muted">${editingNew?'Sin guardar':'Publicado · conexión USB-A'}</p></div>${pill(dirty?'Cambios sin guardar':'Sin cambios',dirty?'warn':'')}</div>`;let fields='';if(direction==='A'){fields=`<section><div class="sectiontitle"><h2>Fotografías</h2>${link('Gestionar','photos')}</div><div class="gallery"><img src="assets/lector.webp" alt="Lector SD UGREEN; portada autorizada">${btn(icon('plus')+' Añadir foto','photos','')}</div>${actionRow('file-text','Nombre y descripción','UGREEN lector SD · USB-A y USB-C','edit-content')}${actionRow('tag','Precio y existencias','$9,00 · 25 unidades · USB-A','edit-sale')}${actionRow('sliders-horizontal','Detalles de venta','Tecnología · Disponible · peso y máximo','edit-more')}<p class="footnote">No hay borrador guardado en el servidor. Al salir con cambios se pide confirmación.</p></section>`;}else{fields=`<div class="tabs" role="tablist" aria-label="Secciones del producto">${[['contenido','Contenido'],['venta','Venta'],['fotos','Fotos']].map(([k,l])=>btn(l,'editortab-'+k,tab===k?'active':'',`role="tab" aria-selected="${tab===k}"`)).join('')}</div><section>${tab==='contenido'?contentFields():tab==='venta'?saleFields():photoFields()}</section>`;}return [content+summary+fields,`<div class="fixed">${btn(editingNew?'Crear producto':'Guardar cambios','save-product')}<p class="caption">${editingNew?'Guardar envía la ficha a la revisión correspondiente.':'Ejemplo sin escritura: no modifica el catálogo.'}</p></div>`];}
function contentFields(){return `<h2>Información que ayuda a elegir</h2><label class="field">Nombre del producto<input name="product-title" value="${editingNew?'':'UGREEN lector SD · USB-A y USB-C'}" placeholder="Nombre y modelo" required></label><label class="field">Descripción<textarea name="description">Lector de tarjetas SD con conexiones USB-A y USB-C. Color gris y negro.</textarea></label><label class="field">Categoría<select name="category"><option>Tecnología</option><option>Audio</option></select></label><label class="field">Características destacadas<textarea name="highlights">USB-A y USB-C\nCompatible con tarjetas SD</textarea><span class="hint">Una por línea · máximo seis</span></label>`;}
function saleFields(){return `<h2>Venta e inventario</h2><p class="small muted" style="margin-top:6px">Ejemplo de precio manual. El precio automático conserva sus reglas y se muestra sin edición.</p><label class="field">Disponibilidad<select name="availability"><option>Disponible</option><option>No disponible · pausa la venta</option><option>Por encargo</option></select></label><label class="field">Variante<input name="variant" value="Conexión USB-A"></label><div class="fieldgrid"><label class="field">Precio · USD<input name="price" inputmode="decimal" value="9,00"></label><label class="field">Existencias<input name="stock" inputmode="numeric" value="25"><span class="hint">Vacío: sin control de cantidad; no equivale a cero.</span></label></div><label class="field">SKU<input name="sku" value="EJ-LECTOR-A"></label>${link('Ver precio automático','auto-price')}${link('Peso, máximo y precio anterior','edit-more')}`;}
function photoFields(){return `<h2>Fotografías · 1 de 10</h2><p class="small muted" style="margin-top:8px">Usa imágenes propias o autorizadas. Portada visible en toda la compra.</p><div class="gallery"><img src="assets/lector.webp" alt="Portada actual del lector SD">${btn(icon('plus')+' Añadir foto','add-photo','')}</div>${link('Usar esta foto como portada','cover')}<p class="small muted">Las fotos nuevas pueden descartarse antes de guardar. Las ya guardadas no se eliminan desde este editor.</p>${photoCredit()}`;}
function orders(){return [heading('Entregas de Voltio',direction==='A'?'Primero, lo pendiente.':'Un pedido.<br>Tu parte de la entrega.','Solo ves las entregas de tu tienda; el pago lo verifica la plataforma.')+`<div class="tabs">${btn('En curso · ejemplo','open-orders','active')}${btn('Cerradas','closed-orders','')}</div><section>${task('EJ-1041 · Entrega 1','Pago confirmado','1 × UGREEN lector SD','Confirmada · lista para preparar','operation','good')}${task('EJ-1038 · Entrega 1','Pago confirmado','2 × Lectores SD','Preparando · despachar','dispatch','good')}${task('EJ-1042 · Entrega 2','Espera de pago','1 × UGREEN lector SD','No preparar todavía','unpaid-operation','warn')}<p class="footnote">Los conteos son de ejemplo. Cada fila representa una entrega, no el importe global del pedido.</p></section>`,sellerbar(direction==='A'?'store':'orders')];}
function operation(){const unpaid=scenario==='unpaid',dispatch=operationStatus==='preparing';return [heading('EJ-1041 · Entrega 1',unpaid?'Primero, el pago.':dispatch?'Lista para despachar.':'Prepara esta entrega.',unpaid?'La acción operativa está bloqueada hasta la confirmación requerida.':'Voltio · envío de vendedor · datos representativos')+`<section class="stack gap24"><div class="row between">${pill(unpaid?'Pago sin confirmar':'Pago confirmado',unpaid?'warn':'good')}${pill(unpaid?'Pendiente':dispatch?'En preparación':'Confirmada')}</div>${unpaid?notice('No prepares ni despaches todavía','La plataforma confirma el pago. Esta pantalla no ofrece aprobar cobros.','warn'):notice('Siguiente tarea habilitada',dispatch?'Registra empresa y guía antes de confirmar el despacho.':'Confirma solo cuando hayas iniciado la preparación. El comprador verá el avance.')}<div><h2>Productos de esta entrega</h2>${product(P[1],1)}</div><div><h2>Destino</h2><p style="margin-top:8px">Ana Ejemplo</p><p class="small muted">Av. Ejemplo · Chacao, Caracas<br>Teléfono ficticio: 0000 000 0000</p><p class="small muted" style="margin-top:8px">A domicilio · guía ${dispatch?'por registrar':'se registra al despachar'}</p></div>${dispatch&&!unpaid?`<div><label class="field">Empresa de envío<input name="carrier" placeholder="Empresa del ejemplo"></label><label class="field">Número de guía · obligatorio<input name="tracking" placeholder="Guía del ejemplo" required></label><div id="tracking-validation" class="errortext" role="alert"></div></div>`:''}<label class="field">Nota al comprador · opcional<textarea name="delivery-note" placeholder="Información útil de esta entrega"></textarea></label>${link('Historial de estados','operation-history')}</section>`,unpaid?`<div class="fixed">${btn('Volver a pedidos','orders','secondary')}<p class="caption">Sin acción de preparación ni despacho.</p></div>`:footer('',null,dispatch?'Revisar despacho':'Revisar preparación','review-operation','Se revalidan permiso, estado y pago antes de actualizar.')];}
function settings(){return [heading('Voltio · Perfil de tienda','Tu negocio,<br>con tu identidad.','Edita la información pública. La aprobación y dirección las administra la plataforma.')+`<section>${actionRow('image','Logo y portada','Recursos propios o autorizados','store-image')}<label class="field">Nombre de tienda<input name="store-name" value="Voltio"></label><label class="field">Descripción<textarea name="store-description">Accesorios para tu día. Tienda de ejemplo del prototipo.</textarea></label><label class="field">Correo de contacto<input name="store-email" type="email" value="tienda@example.com"></label>${actionRow('truck','Información de envíos','Plazos y condiciones informativas','store-shipping')}${actionRow('file-text','Políticas de la tienda','Cambios y devoluciones','policies')}<div class="line row between"><span>Estado de la tienda</span>${pill('Activa','good')}</div><p class="footnote">No hay controles para aprobar tu tienda, editar pagos o cambiar permisos.</p></section>`,footer('',null,'Guardar perfil de ejemplo','save-settings','Los datos del servidor permanecen intactos.')];}
function plan(){const eligible=scenario==='eligible';return [heading('Plan de pago',eligible?'El calendario, claro.':'Un solo pago para este pedido.',eligible?'Escenario alternativo: carrito solo plataforma, elegible. No corresponde al pedido mixto de $59.':'El plan se decide antes de crear el pedido; el método se elige después.')+`<section class="stack gap24">${eligible?`<div>${notice('Ejemplo alternativo independiente','Base $80,00 sin envío, solo stock de plataforma. Estos importes son representativos de un calendario devuelto por servidor. No alteran el pedido mixto.','warn')}${methodRow('deposit','Anticipo 50%','$40,00 hoy · $40,00 el 13 nov.','calendar')}<div class="line row between"><span>Anticipo · 14 oct.</span><b>$40,00 USD</b></div><div class="line row between"><span>Resto · 13 nov.</span><b>$40,00 USD</b></div><p class="small muted" style="margin-top:10px">El vencimiento parte de la creación del pedido, no de la llegada del producto. El saldo sigue en USD.</p>${link('Ver alternativa de tres pagos','three-parts')}</div>`:`${notice('Pago completo · $59,00','Este pedido incluye productos de un vendedor independiente. Los planes de anticipo y cuotas no se ofrecen para este carrito.')}<p class="small muted">Cuando un carrito es elegible, se muestran los importes, recargos y fechas exactas ofrecidos por el servidor. No se reparte un anticipo por vendedor.</p>${link('Abrir escenario alternativo elegible','eligible-plan')}`}</section>`,footer('',null,'Volver al pedido mixto','review','El plan del pedido mixto sigue siendo pago completo.')];}
function stateView(){const empty=scenario==='empty',loading=scenario==='loading',denied=scenario==='permission';if(loading)return [`<section aria-busy="true"><p class="loadingtext" role="status">Cargando ${labels[screen].toLowerCase()}…</p><div class="skeleton short"></div><div class="skeleton tall"></div><div class="skeleton tall"></div><div class="skeleton short"></div></section>`,''];if(denied)return [`<div class="empty">${icon('lock')}<h1>No tienes acceso a esta tienda.</h1><p class="muted">Solo las personas autorizadas pueden gestionar este negocio. Tus compras siguen disponibles.</p>${btn('Volver a Cuenta','account')}</div>`,''];if(empty)return [`<div class="empty">${icon(screen==='cart'?'shopping-bag':screen==='products'?'package':'receipt')}<h1>${screen==='cart'?'Tu carrito está vacío.':screen==='products'?'Tu primer producto empieza aquí.':'Todo al día.'}</h1><p class="muted">${screen==='cart'?'Guarda lo que te interesa y vuelve cuando estés listo.':screen==='products'?'Añade fotos, precio y existencias. La publicación pasa por la revisión que corresponda.':'No hay entregas pendientes. Puedes volver al resumen o revisar el catálogo.'}</p>${btn(screen==='cart'?'Volver al recorrido':screen==='products'?'Crear producto':'Ver resumen',screen==='cart'?'reset':screen==='products'?'new-product':'store')}</div>`,sellerScreens.has(screen)?sellerbar(screen==='products'?'products':'store'):buyerbar('cart')];return [`<div class="empty">${icon('wifi-off')}<h1>No pudimos actualizar.</h1><p class="muted">No confirmamos la operación. Conservamos tus datos en esta visita para que puedas reintentar.</p>${btn('Reintentar','reset')}${link('Volver sin confirmar','back')}</div>`,''];}
const views={cart,delivery,review,method:methods,payment,result,order,account,store,products,editor,orders,operation,settings,plan};
function render(focus=false){if(!views[screen])screen='cart';document.documentElement.dataset.theme=q.get('theme')==='dark'?'dark':'light';$('#prototype').className=direction;$('#top').innerHTML=top();const [body,bottom]=['empty','loading','error','permission'].includes(scenario)?stateView():views[screen]();$('#content').innerHTML=body;$('#bottom').innerHTML=bottom;$('#overlay').innerHTML='';document.title=`${direction} · ${labels[screen]} · HAYAZGO V3`;if(focus){$('#content').scrollTop=0;$('#content').focus({preventScroll:true});}const params=new URLSearchParams({direction,screen,state:scenario,method,theme:q.get('theme')||'light'});history.replaceState(null,'','?'+params);window.parent.postMessage({type:'v3-navigation',direction,screen,scenario},location.origin);}
function go(to,next='normal'){screen=to;scenario=next;render(true);}
let lastFocus=null;
function sheet(title,body,cta='',action='close'){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="dialogback"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="handle"></div><div class="sheethead"><h2 id="sheet-title">${title}</h2>${btn(icon('x'),'close','iconbtn','aria-label="Cerrar hoja"')}</div>${body}${cta?btn(cta,action):''}</section></div>`;setTimeout(()=>$('#overlay button, #overlay input')?.focus(),20);}
function close(){ $('#overlay').innerHTML='';lastFocus?.focus?.(); }
function toast(message){$('#announcer').textContent=message;setTimeout(()=>{$('#announcer').textContent=''},3200);}
function updateDirty(){dirty=true;}
document.addEventListener('input',e=>{if(e.target.closest('.sheet')||screen==='editor'||screen==='settings')updateDirty();if(e.target.id==='product-search'){for(const row of document.querySelectorAll('[data-product]'))row.hidden=!row.dataset.title.includes(e.target.value.toLowerCase());}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
if(action==='back'){if(dirty&&screen==='editor')return sheet('¿Salir sin guardar?',`<p class="muted small">No existe un borrador en el servidor. Puedes seguir editando o descartar los cambios de esta visita.</p>${btn('Seguir editando','close','secondary')}`,'Descartar y salir','discard');return go(backMap[screen]||'cart');}
if(action==='close')return close();if(action==='reset')return go(screen);if(action==='discard'){dirty=false;close();return go('products');}
if(views[action])return go(action);
if(action==='create'){created=true;return go('method');}
if(action==='cash'){method='efectivo_usd';return go('payment');}
if(action==='quote'){if(reported)return go('result');return go('payment');}
if(action.startsWith('method-')){method=action.slice(7);return render();}
if(action==='address')return sheet('Dirección del pedido',`<p class="small muted">Se aplica a todas las entregas; no hay dirección por vendedor.</p>${['Casa','Oficina'].map((v,i)=>`<button class="choice ${selectedAddress===v?'selected':''}" data-action="addresschoose-${v}"><span class="radio"></span><span><b>${v} · Ana Ejemplo</b><small class="muted" style="display:block">${i?'Av. Prueba, Chacao':'Av. Ejemplo, Chacao'} · Caracas</small></span></button>`).join('')}${link('Editar dirección','edit-address')}`,'Usar dirección y revisar entregas','apply-address');
if(action.startsWith('addresschoose-')){selectedAddress=action.slice(14);return sheet('Dirección elegida',`<p>${selectedAddress} · Ana Ejemplo</p><p class="small muted">Se recalcularán ambas entregas y su total antes de confirmar.</p>`,'Aplicar y revisar','apply-address');}
if(action==='apply-address'){close();return go('delivery');}
if(action==='edit-address')return sheet('Editar dirección',`<label class="field">Destinatario<input value="Ana Ejemplo"></label><label class="field">Teléfono<input value="0000 000 0000" inputmode="tel"></label><label class="field">Ciudad<input value="Caracas"></label><label class="field">Dirección<textarea>Av. Ejemplo, Chacao. Datos ficticios del prototipo.</textarea></label><p class="small muted">La región/ciudad y los campos completos se conservan en la implementación existente.</p>`,'Usar en el prototipo','apply-address');
if(action.startsWith('shipping-'))return sheet('Modalidad de esta entrega',`<button class="choice selected" data-action="close"><span class="radio"></span><span class="grow"><b>A domicilio</b><small class="muted" style="display:block">16–19 oct. · ejemplo de respuesta</small></span><b>$4,00</b></button><p class="footnote">Este escenario solo incluye una modalidad elegible. La app debe mostrar únicamente las opciones devueltas para este grupo y dirección.</p>`,'Conservar modalidad','close');
if(action.startsWith('quantity-'))return sheet('Cantidad y disponibilidad',notice('Solo hay una unidad en este escenario','La interfaz revalida contra existencias; no muestra un total calculado en el cliente.','warn'),'Conservar una unidad','stock-issue');
if(action==='stock-issue'){close();return go('cart','stock');}
if(action.startsWith('remove-'))return sheet('Quitar del carrito',`<p class="muted small">Esta acción quita el producto, no cancela ningún pedido creado.</p><p class="footnote">La demostración abre el estado de carrito vacío para revisar su recuperación.</p>`,'Ver carrito vacío de ejemplo','empty-cart');
if(action==='empty-cart'){close();return go('cart','empty');}
if(action==='proof'){window.proofAttached=true;return render();}
if(action==='copy')return toast('Dato ficticio: la simulación no copia información bancaria real.');
if(action==='rate')return sheet('Conversión del ejemplo',`<div class="totals"><span>Referencia histórica</span><b>877,90 Bs/USD</b><span>Fecha valor</span><b>14 oct. 2026</b><span>Procedencia</span><b>DolarAPI · respaldo BCV</b></div><p class="footnote">Tomada de la evidencia remota ya registrada el 14 oct.; no se consultan ni modifican tasas aquí. No es una cotización vigente para pagar.</p>${notice('Son fechas distintas','Fecha de la tasa, emisión y vencimiento de la cotización deben mostrarse por separado. Renovar el monto no rejuvenece la tasa.')}`,'Entendido','close');
if(action==='report'){const reference=$('input[name=reference]')?.value.trim();if(method!=='efectivo_usd'&&!reference){$('#payment-validation').textContent='Escribe la referencia bancaria para continuar.';return $('input[name=reference]').focus();}if(method==='transferencia_ves'&&!window.proofAttached){$('#payment-validation').textContent='Adjunta el comprobante requerido por transferencia.';return;}reported=true;return go('result');}
if(action==='renew')return go('payment');if(action==='retry-payment'){reported=false;return go('method');}
if(action==='other-methods')return sheet('USDT · método manual',`<p class="small muted">USDT TRC-20 aparece habilitado en el diagnóstico registrado. Exige el hash de 64 caracteres; el comprobante es opcional. La cotización debe indicar red, dirección e importe.</p>${notice('No se inventa un importe','La maqueta no calcula el tipo de cambio de este método. Binance Pay y PayPal no se presentan como habilitados.')}`,'Ver selección USDT','choose-usdt');
if(action==='choose-usdt'){method='usdt_trc20';close();return go('payment');}
if(action==='eligible-plan')return go('plan','eligible');
if(action==='three-parts')return sheet('Tres pagos · otro escenario',`<p class="small muted">Ejemplo independiente de respuesta: total $90,00; financiamiento $0,00 en esta fixture; 3 obligaciones de $30,00.</p><div class="line row between"><span>14 oct. · pago inicial</span><b>$30,00</b></div><div class="line row between"><span>29 oct. · cuota 2</span><b>$30,00</b></div><div class="line row between"><span>13 nov. · cuota 3</span><b>$30,00</b></div><p class="footnote">Importes, recargo y calendario pertenecen al servidor. No trasladar este plan al pedido mixto. Pagos futuros en VES se convierten con una nueva cotización.</p>`,'Volver al anticipo de ejemplo','close');
if(action==='order-history')return sheet('Calendario y movimientos',`<div class="line row between"><span>Pago completo</span><b>$59,00 USD</b></div><p class="small muted">El saldo permanece en dólares. Una nueva conversión requiere cotización vigente.</p><div class="line"><strong>${reported?'Reporte pendiente de verificación':'Sin pagos confirmados'}</strong></div>`,'Cerrar','close');
if(action==='tracking')return sheet('Seguimiento por entrega',`<h3>1 · HAYAZGO</h3><p class="small muted">Preparación pendiente · sin guía todavía.</p><div class="divider"></div><h3>2 · Voltio</h3><p class="small muted">Confirmada · la tienda actualiza su avance.</p>`,'Volver al pedido','close');
if(action==='cancel-order')return sheet('Cancelar depende del estado',`<p class="small muted">La acción solo se ofrece cuando el pedido actual la permite. No se promete devolución automática ni reposición inmediata del carrito.</p>`,'Conservar el pedido','close');
if(action==='dispatch'){operationStatus='preparing';return go('operation');}if(action==='unpaid-operation')return go('operation','unpaid');
if(action==='review-operation'){if(operationStatus==='preparing'&&!$('input[name=tracking]')?.value.trim()){$('#tracking-validation').textContent='Registra la guía antes de revisar el despacho.';return $('input[name=tracking]').focus();}return sheet(operationStatus==='preparing'?'Confirmar despacho':'Confirmar preparación',`<p class="small muted">Entrega 1 del pedido de ejemplo EJ-1041. Confirma que completaste esta tarea. El comprador podrá ver el avance.</p>${notice('Simulación aislada','La implementación debe volver a consultar permisos, estado y pago. Este prototipo no actualiza ninguna entrega.')}`,'Confirmar en el prototipo','confirm-operation');}
if(action==='confirm-operation'){close();if(operationStatus==='preparing'){toast('Escenario de despacho completado; ningún pedido real fue modificado.');return go('orders');}operationStatus='preparing';go('operation');return toast('Preparación representada. Siguiente tarea: registrar guía para despacho.');}
if(action==='operation-history')return sheet('Historial de la entrega',`<div class="timeline"><div class="event"><strong>Pedido creado · 13 oct.</strong><p>Origen: plataforma</p></div><div class="event active"><strong>Pago confirmado</strong><p>La plataforma habilitó la siguiente tarea</p></div></div>`,'Cerrar','close');
if(action==='new-product'){editingNew=true;dirty=false;editorTab='contenido';return go('editor');}
if(action==='inventory')return sheet('Existencias · conexión USB-A',`<p class="small muted">UGREEN lector SD. Edición de una variante; no operación masiva.</p><label class="field">Unidades disponibles<input name="quick-stock" inputmode="numeric" value="25"></label><p class="footnote">Vacío equivale a sin control de cantidades. No confundir con agotado.</p>`,'Revisar cambio','inventory-review');
if(action==='inventory-review')return sheet('Guardar cambio de existencias',`<p class="small muted">Se enviaría el producto con su variante al guardado existente. Moderación y disponibilidad conservan las reglas actuales.</p>`,'Guardar en la simulación','inventory-saved');
if(action==='inventory-saved'){close();return toast('Existencias representadas como guardadas; sin escritura real.');}
if(action.startsWith('editortab-')){editorTab=action.slice(10);return render();}
if(action==='edit-content')return sheet('Contenido del producto',contentFields(),'Conservar cambios en esta visita','keep-editor');
if(action==='edit-sale')return sheet('Precio y existencias',saleFields(),'Conservar cambios en esta visita','keep-editor');
if(action==='edit-more')return sheet('Detalles de venta',`<div class="fieldgrid"><label class="field">Peso · kg<input value="0,1" inputmode="decimal"></label><label class="field">Máximo por pedido<input value="5" inputmode="numeric"></label></div><label class="field">Precio anterior · opcional<input inputmode="decimal" placeholder="Solo si se vendió a ese precio"></label><p class="footnote">Las validaciones y límites comerciales existentes se mantienen.</p>`,'Conservar en esta visita','keep-editor');
if(action==='photos')return sheet('Fotografías',photoFields(),'Conservar selección','keep-editor');
if(action==='keep-editor'){dirty=true;close();return render();}
if(action==='add-photo')return sheet('Seleccionar foto de ejemplo',`<img class="thumb large" src="assets/lector.webp" alt="Foto autorizada de UGREEN lector"><p class="footnote">En el prototipo se reutiliza un recurso autorizado. En la app se conserva el selector de galería existente; no se sube nada aquí.</p>`,'Añadir solo a esta simulación','photo-added');
if(action==='photo-added'){dirty=true;close();toast('Nueva foto de ejemplo elegida. Puedes descartarla antes de guardar.');return;}
if(action==='cover'){dirty=true;return toast('Foto elegida como portada dentro de esta simulación.');}
if(action==='auto-price')return sheet('Precio automático existente',`<label class="field">Precio calculado · USD<input readonly value="9,00"></label><label class="field">Costo de ejemplo · USD<input inputmode="decimal" value="6,00"></label><p class="small muted">El precio depende de las reglas vigentes del servidor. Sin cálculo válido se conserva el último precio y se informa. No hay cambio de modo de precio desde esta maqueta.</p>`,'Volver al editor','close');
if(action==='save-product'){const title=$('input[name=product-title]');if(title&&!title.value.trim()){title.setAttribute('aria-invalid','true');title.focus();return toast('Completa el nombre del producto antes de guardar.');}dirty=false;return sheet('Producto guardado · ejemplo',`<p>La ficha se envió a la revisión correspondiente.</p>${notice('Guardado no significa publicado','Estado representado: en revisión. Solo una aprobación real lo hará visible según las reglas del catálogo.','warn')}`,'Volver a productos','products');}
if(action==='save-settings')return sheet('Perfil guardado · ejemplo',`<p class="small muted">Confirmación visual. Ninguna tienda del servidor fue modificada.</p>`,'Volver a Mi tienda','store');
if(action==='stores')return sheet('Tus tiendas autorizadas',`<button class="choice selected" data-action="close"><span class="radio"></span><span><b>Voltio</b><small class="muted" style="display:block">Activa · tienda representativa</small></span></button><p class="footnote">El selector se muestra si existen varias pertenencias. No permite elegir una tienda ajena.</p>`,'Continuar en Voltio','close');
if(action.startsWith('productfilter-')){const idx=Number(action.slice(14));document.querySelectorAll('.filtertags button').forEach((b,i)=>{b.classList.toggle('active',i===idx);b.setAttribute('aria-pressed',String(i===idx));});for(const row of document.querySelectorAll('[data-product]'))row.hidden=idx===1?row.dataset.product==='2':idx===2?row.dataset.product!=='2':false;return;}
if(action==='closed-orders')return sheet('Entregas cerradas',`<p class="small muted">Sin entregas cerradas en este escenario. Se conserva la consulta existente y su límite; no se inventa historial.</p>`,'Volver a En curso','close');if(action==='open-orders')return;
if(['policies','store-shipping','store-image'].includes(action))return sheet(action==='policies'?'Políticas públicas':action==='store-image'?'Logo y portada':'Información de envíos',`<p class="small muted">Estos campos ya existen en el perfil de tienda. ${action==='store-image'?'Usa recursos propios o autorizados; el prototipo no abre una carga real.':'Texto informativo, no cambia tarifas ni obligaciones del pedido.'}</p><label class="field">Contenido de ejemplo<textarea>Información de la tienda de ejemplo, editable solo en este prototipo.</textarea></label>`,'Conservar en el prototipo','close');
if(['support','favorites','preferences'].includes(action))return sheet(action==='support'?'Ayuda con el pedido':action==='favorites'?'Favoritos conservados':'Preferencias conservadas',`<p class="small muted">Este destino existente queda fuera de la etapa V3. El prototipo conserva el acceso sin rediseñar ese recorrido ni enviar mensajes.</p>`,'Volver al recorrido','close');
});
document.addEventListener('keydown',e=>{const dialog=$('[role=dialog]');if(!dialog)return;if(e.key==='Escape'){e.preventDefault();return close();}if(e.key==='Tab'){const focusables=[...dialog.querySelectorAll('button:not([disabled]),input,textarea,select,a[href]')];const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
render();

})();
